-- ============================================================
-- RDM-ENTITY-001 · PHASE 2A.1 — corrective migration (additive)
-- ============================================================

-- ------------------------------------------------------------
-- A. Licence number is NOT an entity identifier
--    A licence number identifies a licence/authorisation
--    (licenses.license_number), never the legal/regulatory entity.
--    Remove ONLY rows provably generated by the Phase 2A backfill.
-- ------------------------------------------------------------
DO $$
DECLARE v_type uuid; v_removed integer := 0; v_remaining integer;
BEGIN
  SELECT id INTO v_type FROM public.entity_identifier_types WHERE key = 'license_number';
  IF v_type IS NOT NULL THEN
    DELETE FROM public.entity_identifiers
     WHERE identifier_type_id = v_type
       AND source_type = 'LEGACY_BACKFILL'
       AND source_reference LIKE 'licenses.license_number:%';
    GET DIAGNOSTICS v_removed = ROW_COUNT;

    SELECT count(*) INTO v_remaining FROM public.entity_identifiers WHERE identifier_type_id = v_type;

    UPDATE public.entity_identifier_types
       SET is_active = false,
           description = 'RETIRED (Phase 2A.1): a licence number identifies a licence/authorisation and remains authoritative on licenses.license_number. It is not entity identity. It may later act as an entity-resolution lookup signal through entity_licenses.'
     WHERE id = v_type;

    RAISE NOTICE 'Phase 2A.1: removed % licence-number entity identifiers (% licence-number identifier rows remain, type retired)', v_removed, v_remaining;
  END IF;
END $$;

-- ------------------------------------------------------------
-- B. Controlled identifier normalization strategy
-- ------------------------------------------------------------
ALTER TABLE public.entity_identifier_types
  ADD COLUMN IF NOT EXISTS normalization_strategy text NOT NULL DEFAULT 'UPPER_ALPHANUMERIC';

ALTER TABLE public.entity_identifier_types
  DROP CONSTRAINT IF EXISTS eit_normalization_strategy_chk;
ALTER TABLE public.entity_identifier_types
  ADD CONSTRAINT eit_normalization_strategy_chk CHECK (
    normalization_strategy = ANY (ARRAY[
      'UPPER_TRIM','UPPER_ALPHANUMERIC','DIGITS_ONLY','TRIM_ONLY','CASE_SENSITIVE_TRIM'
    ])
  );

COMMENT ON COLUMN public.entity_identifier_types.normalization_strategy IS
  'Engine normalization algorithm applied before comparison/uniqueness. Executed by public.normalize_entity_identifier(). Administrators select a strategy; arbitrary SQL/regex/expressions are never executed.';

UPDATE public.entity_identifier_types SET normalization_strategy = 'UPPER_ALPHANUMERIC'
  WHERE key IN ('company_registration_number','regulatory_entity_number','license_number');
UPDATE public.entity_identifier_types SET normalization_strategy = 'DIGITS_ONLY'
  WHERE key = 'taxpayer_registration_number';
UPDATE public.entity_identifier_types SET normalization_strategy = 'UPPER_TRIM'
  WHERE key = 'legal_entity_identifier';

-- descriptive free text replaced by the controlled strategy
ALTER TABLE public.entity_identifier_types DROP COLUMN IF EXISTS normalization_rule;

-- One canonical normalization service. The external registry matching layer
-- (Phase 3) MUST call this same function.
CREATE OR REPLACE FUNCTION public.normalize_entity_identifier(_identifier_type_id uuid, _raw_value text)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_strategy text; v text := btrim(COALESCE(_raw_value, ''));
BEGIN
  SELECT normalization_strategy INTO v_strategy
    FROM public.entity_identifier_types WHERE id = _identifier_type_id;
  IF v_strategy IS NULL THEN
    RAISE EXCEPTION 'Unknown identifier type %', _identifier_type_id USING ERRCODE = '23503';
  END IF;

  CASE v_strategy
    WHEN 'TRIM_ONLY'           THEN NULL;
    WHEN 'CASE_SENSITIVE_TRIM' THEN v := regexp_replace(v, '\s+', ' ', 'g');
    WHEN 'UPPER_TRIM'          THEN v := upper(regexp_replace(v, '\s+', ' ', 'g'));
    WHEN 'UPPER_ALPHANUMERIC'  THEN v := upper(regexp_replace(v, '[^A-Za-z0-9]', '', 'g'));
    WHEN 'DIGITS_ONLY'         THEN v := regexp_replace(v, '[^0-9]', '', 'g');
    ELSE RAISE EXCEPTION 'Unsupported normalization strategy %', v_strategy USING ERRCODE = '22023';
  END CASE;

  RETURN v;
END $$;

REVOKE ALL ON FUNCTION public.normalize_entity_identifier(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.normalize_entity_identifier(uuid, text) TO authenticated, service_role;

-- Trigger now delegates normalization and refuses retired identifier types.
CREATE OR REPLACE FUNCTION public.entity_identifier_normalize()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE v_scope text; v_active boolean; v_key text;
BEGIN
  SELECT uniqueness_scope, is_active, key INTO v_scope, v_active, v_key
    FROM public.entity_identifier_types WHERE id = NEW.identifier_type_id;
  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unknown identifier type %', NEW.identifier_type_id USING ERRCODE = '23503';
  END IF;
  IF NOT v_active THEN
    RAISE EXCEPTION 'Identifier type "%" is retired and cannot be used for entity identity', v_key USING ERRCODE = '23514';
  END IF;

  NEW.uniqueness_scope := v_scope;
  NEW.normalized_value := public.normalize_entity_identifier(NEW.identifier_type_id, NEW.identifier_value);
  IF NULLIF(btrim(COALESCE(NEW.normalized_value, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Identifier value normalises to an empty string under the configured strategy' USING ERRCODE = '22023';
  END IF;

  IF v_scope = 'JURISDICTION' AND NEW.jurisdiction_id IS NULL THEN
    RAISE EXCEPTION 'Identifier type requires a jurisdiction (uniqueness_scope = JURISDICTION)' USING ERRCODE = '23514';
  END IF;
  IF v_scope = 'ISSUER' AND NULLIF(btrim(COALESCE(NEW.issuer_key, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Identifier type requires an issuer (uniqueness_scope = ISSUER)' USING ERRCODE = '23514';
  END IF;
  IF v_scope = 'REGULATOR' AND NEW.regulator_id IS NULL THEN
    RAISE EXCEPTION 'Identifier type requires a regulator (uniqueness_scope = REGULATOR)' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END $$;

-- ------------------------------------------------------------
-- C. Regulatory entities are historically durable — no cascade
-- ------------------------------------------------------------
ALTER TABLE public.entity_licenses
  DROP CONSTRAINT IF EXISTS entity_licenses_entity_id_fkey;
ALTER TABLE public.entity_licenses
  ADD CONSTRAINT entity_licenses_entity_id_fkey
  FOREIGN KEY (entity_id) REFERENCES public.licensees(id) ON DELETE RESTRICT;

ALTER TABLE public.entity_identifiers
  DROP CONSTRAINT IF EXISTS entity_identifiers_entity_id_fkey;
ALTER TABLE public.entity_identifiers
  ADD CONSTRAINT entity_identifiers_entity_id_fkey
  FOREIGN KEY (entity_id) REFERENCES public.licensees(id) ON DELETE RESTRICT;

ALTER TABLE public.applications
  DROP CONSTRAINT IF EXISTS applications_entity_id_fkey;
ALTER TABLE public.applications
  ADD CONSTRAINT applications_entity_id_fkey
  FOREIGN KEY (entity_id) REFERENCES public.licensees(id) ON DELETE RESTRICT;

COMMENT ON CONSTRAINT entity_licenses_entity_id_fkey ON public.entity_licenses IS
  'RESTRICT: a regulated entity is closed/retired/merged, never physically deleted. Controlled Entity Merge is a later phase.';

-- ------------------------------------------------------------
-- D. Entity-licence temporal integrity
--    Every existing row already carries a real effective_from
--    (verified 0 NULLs) — no date is fabricated.
-- ------------------------------------------------------------
DO $$
DECLARE v_null integer;
BEGIN
  SELECT count(*) INTO v_null FROM public.entity_licenses WHERE effective_from IS NULL;
  IF v_null > 0 THEN
    RAISE EXCEPTION 'Refusing to enforce NOT NULL: % entity_licenses rows have an unknown effective_from. Model an explicit provenance/unknown-date strategy instead of substituting now().', v_null;
  END IF;
  ALTER TABLE public.entity_licenses ALTER COLUMN effective_from SET NOT NULL;
END $$;

ALTER TABLE public.entity_licenses DROP CONSTRAINT IF EXISTS entity_licenses_period_valid;
ALTER TABLE public.entity_licenses
  ADD CONSTRAINT entity_licenses_period_valid CHECK (effective_to IS NULL OR effective_to >= effective_from);